    const empty = generateChangelogEntry("1.0.1", parseCommitLog("chore: x"), "2026-06-27");
    expect(empty).toContain("## [1.0.1] - 2026-06-27");
    expect(empty).toMatch(/no notable changes/i);
  });
});

