// ---------------------------------------------------------------------------
// CLI
// ---------------------------------------------------------------------------

/** Minimal flag parser: supports `--flag value` and boolean `--flag`. */
function parseArgs(argv: string[]): Record<string, string | boolean> {
  const out: Record<string, string | boolean> = {};
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i]!;
